import * as M from './meaning-engine.js';
import {studyItem,canonicalId,goalLabel,eligible,dayKey} from './engine.js';
import {meaningResult} from './learning-flow.js';
import {needsContextAudio} from './word-card.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(text,route,cls='btn')=>`<a class="${cls}" href="#${esc(route)}">${esc(text)}</a>`;
const date=at=>new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric'}).format(new Date(at));
const family=(lib,id)=>lib.families.find(f=>f.id===id);
const exit=()=>link('‹ 退出','today','study-exit');
export function renderMeaning(lib,s,now=Date.now(),busy=false,fid,saved=true){
  const ss=s.meaningSession,d=M.ensureMeaningDay(s,lib,now),saving=busy?'disabled aria-disabled="true"':'';
  if(!ss)return `<div class="reader-page meaning-page"><section class="card reader-empty"><h1>当前没有待学任务</h1><p>到期词会自动加入学习。今天可以轻松收尾。</p>${link('返回学习','today')} ${link('探索词族','families','btn outline')}</section></div>`;
  if(!ss.queue.length){
    const result=meaningResult(s,lib,now),f=family(lib,ss.lastFamily||d.family),light=ss.mode==='light';
    const closing=result.daily?'今天可以到这里，明天再接着巩固。':d.checked?'这次额外练习已记下，今天可以到这里。':light?`这一组 ${ss.total} 个词或义项已练完，剩余任务还在，可以到这里。`:'今日还有其他待学内容，继续完成后会自动打卡。';
    return `<div class="reader-page meaning-page"><header class="study-bar">${exit()}<span>学习结果</span></header><section class="card reader-finish"><span class="reader-done">✓</span><h1 class="mt">${result.daily?'今天的学习完成了':'这一组完成了'}</h1><div class="result-counts"><div><strong>${result.newCount}</strong><span>${result.daily?'今日':'本轮'}新学</span></div><div><strong>${result.reviewCount}</strong><span>${result.daily?'今日':'本轮'}复习</span></div><div><strong>${result.weak}</strong><span>待巩固</span></div></div><p>${closing}</p><p class="completion-save" role="status">${busy?'正在保存这次记录…':saved?'本次记录已保存。':'记录暂未保存，请先重试保存。'}</p>${result.next!==null&&Number.isFinite(result.next)?`<div class="notice">最近一次复习：${date(result.next)}。每个词分别安排。</div>`:''}<div class="mt"><button class="btn" data-action="meaning-finish" ${saving}>${result.daily||d.checked?'结束今天':light?'到这里':'继续今日学习'}</button></div><details class="completion-more"><summary>复习安排与更多选择</summary><div class="row mt">${light&&!result.daily&&!d.checked?`<button class="btn small outline" data-action="meaning-continue" ${saving}>继续今日学习</button>`:''}${link('查看复习安排','review','btn small outline')}${link('回看词族导图','family/'+f.id,'btn small outline')}${s.settings.target&&M.meaningCandidates(s,lib,f).length?`<button class="btn small outline" data-action="meaning-more" data-id="${esc(f.id)}" ${saving}>再学一组本词族</button>`:''}</div><p class="meta">记录这一次的回忆，后续仍会复习。</p></details></section></div>`;
  }
  const q=ss.queue[0],w=studyItem(lib,q.id),f=family(lib,q.family),shown=q.phase==='revealed',ex=w.examples?.[q.contextIndex]||{text:w.example,translation:w.translation},context=w.isAdditionalSense||(lib.words[canonicalId(w.id)].studyItemIds||[]).length>1,ipa=w.ipa?.uk||w.ipa?.us,attrs=`data-session="${esc(ss.id)}" data-token="${esc(q.token)}"`;
  const header=`<header class="study-bar">${exit()}<h1>${ss.mode==='light'?'轻量 · ':''}${esc(f.label)} · ${q.reinforcement?'巩固':q.new?'新学':'复习'}</h1><span class="study-position">${ss.finished.length} / ${ss.total}</span></header>`;
  const word=`<section class="reader-word meaning-word"><h2 lang="en">${esc(w.word)}</h2><div class="reader-pronunciation">${ipa?`<span lang="en">${esc(ipa)}</span>`:''}<button class="reader-sound" data-action="speak" data-id="${esc(w.id)}" data-accent="${w.ipa?.uk?'en-GB':'en-US'}">${needsContextAudio(w,lib)?'例句朗读':'朗读'}</button></div></section>`;
  const answer=shown?`<section class="meaning-answer" aria-label="词义答案"><div class="reader-definition"><span>${esc(w.pos)}</span><p>${esc(w.meaning)}</p></div><section class="reader-association"><span>构词与记忆线索</span><strong lang="en">${esc(w.parts.map(x=>x.text).join(' + '))}</strong><p>${esc(w.mnemonic)}</p></section><section class="reader-example"><p lang="en">${esc(ex.text)}</p><p>${esc(ex.translation)}</p></section><details class="reader-more"><summary>展开构词解释与完整词卡</summary><p class="mt">${esc(w.explanation)}</p><p class="muted mt">${esc(w.posHint)}</p><div class="row mt"><button class="btn small outline" data-word="${esc(q.id)}">打开完整词卡</button>${link('查看词族导图','family/'+f.id,'btn small outline')}</div></details></section>`:`<section class="meaning-question"><p>先回忆${context?'句子中的词义':'这个词的意思'}，再揭示确认。</p>${context?`<p class="meaning-context" lang="en">${esc(ex.text)}</p>`:''}</section>`;
  const warm=s.settings.encouragement!=='plain',ratings=[['forgot','没想起','没想起或想错','慢慢来'],['fuzzy','没想全','不完整或借助提示','想起一些'],['clear','已想对','揭示前已独立想对','这次想对']];
  const controls=shown?`<div class="reader-controls meaning-controls"><p class="meaning-rate-guide">${q.aided?'已查看提示，本次按辅助回忆记录':'记录揭示前的回忆'}</p>${ratings.map(([grade,label,help,friendly])=>`<button class="btn meaning-grade ${grade} ${warm?'warm-copy':''}" data-action="meaning-grade" data-grade="${grade}" ${attrs} ${saving} aria-label="${warm?friendly+'，':''}${label}：${help}" title="${help}"><strong>${warm?friendly:label}</strong>${warm?`<span class="meaning-grade-state">${label}</span>`:''}</button>`).join('')}</div>`:`<div class="reader-controls meaning-controls single"><button class="btn meaning-reveal" data-action="meaning-reveal" ${attrs} ${saving} aria-label="查看 ${esc(w.word)} 的词义">查看词义</button></div>`;
  const phase=q.reinforcement?`继续巩固 · 本词第 ${q.repeats} 次再回忆`:'';
  return `<div class="reader-page meaning-page" data-meaning-session="${esc(ss.id)}" data-meaning-word="${esc(q.id)}" data-meaning-phase="${q.phase}">${header}<article class="reader-card card"><div class="reader-meter" role="progressbar" aria-label="本轮已评分义项，巩固完成后结束" aria-valuemin="0" aria-valuemax="${ss.total}" aria-valuenow="${ss.finished.length}"><span style="width:${ss.finished.length*100/ss.total}%"></span></div>${phase?`<p class="study-phase">${phase}</p>`:''}${word}${answer}</article>${controls}<p class="reader-note" role="status">${busy?'正在保存…':phase}</p></div>`;
}
export function renderMeaningToday(lib,s,now=Date.now()){
  const d=M.ensureMeaningDay(s,lib,now),p=M.meaningProgress(d,s),f=family(lib,d.family),ss=s.meaningSession,old=s.session;
  const remainingNew=d.newIds.length-p.newDone,remainingReview=d.reviewIds.length-p.reviewDone,done=p.ready&&d.checked,active=ss?.queue.length;
  const previous=Object.keys(s.meaningDays).some(k=>k<dayKey(now)&&s.meaningDays[k].completed.length),light=ss?.mode==='light';
  const title=active?(d.checked?'额外学习进行中':light?'先完成这一小组':'从这里接着'):ss&&!ss.queue.length?'查看这次学习的结果':done?'今天已完成':d.checked?'今天已打卡，可继续额外学习':p.done?`今天已练 ${p.done} 个词或义项`:p.total?previous?'欢迎回来，按自己的节奏来':'今天，按自己的节奏来':'今天没有待学任务';
  const description=active?`本轮已评分 ${ss.finished.length} / ${ss.total}${ss.finished.length===ss.total?'，还有巩固卡需要回忆。':'，从上次的词继续。'}`:done?`今日新学 ${p.newDone} 个，复习 ${p.reviewDone} 个。`:p.total?`${remainingReview?`先复习 ${remainingReview} 个词或义项；`:'今天没有到期词；'}${remainingNew?`再学 ${f.label} 词族的 ${remainingNew} 个新词或义项。`:'本次只安排复习。'}`:'到期词会自动加入任务。';
  const primary=ss?link(ss.queue.length?'继续学习':'查看学习结果','read'):p.total&&!done?link(d.checked?'继续额外学习':p.done?'继续学习':'开始学习','read'):'';
  return `<header class="page-head"><div><h1>学习</h1><p>从一组开始，按自己的节奏继续。</p></div>${link(goalLabel(s),'me','pill')}</header><section class="card learning-home today-family"><span class="eyebrow">${d.checked?'今日已打卡':active?light?'轻量一组进行中':'词义回忆进行中':p.done?'今日已有练习':'今日计划'}</span><h2>${title}</h2><p class="learning-plan-copy">${esc(description)}</p><div class="home-counts"><div><strong>${remainingReview}</strong><span>待复习</span></div><div><strong>${remainingNew}</strong><span>待学新词</span></div></div>${p.total?`<div class="progress" role="progressbar" aria-label="今日已评分词或义项，巩固完成后打卡" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.done}"><span style="width:${100*p.done/p.total}%"></span></div>`:''}${primary}${!ss&&!done&&p.total>p.done?`<div class="light-choice"><button class="today-map-link light-start" data-action="meaning-light">今天少学一点</button><span>先练最多 5 个词或义项，包含需要的巩固。</span></div>`:''}${d.resumedFrom?`<p class="target-note">从 ${esc(d.resumedFrom)} 那轮接着，按今天的回忆记录。</p>`:''}<div class="learning-home-links">${link('复习安排','review','today-map-link')}${link(old?'专项练习 · 有未完进度':'专项练习','special','today-map-link')}</div></section>`;
}
export function renderMeaningReview(lib,s,now=Date.now()){
  const groups=M.meaningGroups(s,lib,now),due=groups.flatMap(g=>g.ids),upcoming=Object.keys(s.meanings||{}).filter(id=>!due.includes(id)&&eligible(s,lib,id)&&s.meanings[id].due>now).sort((a,b)=>s.meanings[a].due-s.meanings[b].due).slice(0,8);
  return `<header class="page-head"><div><h1>复习安排</h1><p>到期内容已包含在今日学习里，每个词分别安排日期。</p></div>${link('返回学习','today','btn outline')}</header><section class="card review-banner"><span class="eyebrow">今天到期 · ${groups.length} 个词族</span><div class="review-count">${due.length}<span> 个词或义项</span></div><p class="muted">${due.length?'从学习入口开始，会先处理到期词。':'今天没有到期词。后续安排会自动加入学习。'}</p></section>${groups.length?`<details class="card mt"><summary>按词族查看到期内容</summary><div class="grid family-grid mt">${groups.map(g=>{const f=family(lib,g.family);return `<section class="card due-family"><span class="tag warm">${g.ids.length} 个到期义项</span><h2>${esc(f.label)}</h2><button class="btn small mt" data-action="meaning-review" data-id="${esc(f.id)}">只复习这一族</button></section>`;}).join('')}</div></details>`:''}<section class="card mt"><h2>接下来的复习安排</h2>${upcoming.length?`<div class="list">${upcoming.map(id=>{const w=studyItem(lib,id);return `<div class="list-item"><button class="word-link" data-word="${esc(id)}">${esc(w.word)}${w.isAdditionalSense?' · 拓展义项':''}</button><span class="tag">${date(s.meanings[id].due)}</span></div>`;}).join('')}</div>`:'<p class="muted mt">完成词义评分后，这里会显示每个词的日期。</p>'}</section>`;
}
